18|typedef struct yaml_output_buffer {
19|  unsigned char *buf;
20|  size_t size;
21|  size_t capacity;
22|} yaml_output_buffer_t;
23|
24|static int yaml_write_handler(void *data, unsigned char *buffer, size_t size) {
25|  size_t newsize;
26|  yaml_output_buffer_t *out = (yaml_output_buffer_t *)data;
27|
28|  /* Double buffer size whenever necessary */
29|  if (out->size + size >= out->capacity) {
30|    newsize = out->capacity << 1;
31|    if (newsize < out->size + size) {
32|      newsize = out->size + size;
33|    }
34|    out->buf = (unsigned char *)realloc(out->buf, newsize);
35|    out->capacity = newsize;
36|  }
37|  if (!out->buf) {
38|    out->size = 0;
39|    return 0;
40|  }
41|
42|  memcpy(out->buf + out->size, buffer, size);
43|  out->size += size;
44|  return 1;
45|}
